"""
What an order came to. `ok` unless refused; `outcome` is the venue's word; a refusal's `reason` is the venue's own
sentence, `kind` the word a program branches on, `remedy` what to change and `docs` the page. `raw` is the whole answer.
"""
struct Answer
    ok::Bool
    outcome::String
    reason::Union{Nothing,String}
    kind::Union{Nothing,String}
    remedy::Union{Nothing,String}
    docs::Union{Nothing,String}
    ticket::Any
    order::Any
    raw::Any
end

function Answer(raw)
    last = raw isa AbstractDict ? get(raw, "last_answer", nothing) : nothing
    pick(k) = (v = raw isa AbstractDict ? get(raw, k, nothing) : nothing; v !== nothing ? v : (last isa AbstractDict ? get(last, k, nothing) : nothing))
    o = pick("outcome")
    outcome = o isa AbstractString && !isempty(o) ? String(o) : "sent"
    Answer(outcome != "refused", outcome, pick("reason"), pick("kind"), pick("remedy"), pick("docs"), pick("ticket"), pick("order"), raw)
end

"A refusal raised, when the workbench was opened with `raise_refusals`: the answer is on it."
struct Refused <: BentrixException
    answer::Answer
end
Base.showerror(io::IO, e::Refused) = print(io, something(e.answer.reason, e.answer.outcome))

"""
What a Bench reaches its workbench through, `_door_call(door, name, args)`: the connection to a running Bentrix (a
`Client`), the engine in this process (a `Bentrix.Local`, whose method is the package's), or any function `(name, args)`.
"""
_door_call(c::Client, name, args) = call(c, name, args)
_door_call(f::Function, name, args) = f(name, args)

"A workbench: its orders, its book, its clock and its state, through either door."
mutable struct Bench
    client::Any
    uri::String
    name::Union{Nothing,String}
    raise::Bool
    markets::Union{Nothing,Vector{String}}
    mounted::Bool
end

"A workbench: the one named (its name or its address), else the selected one, else the first."
function open_bench(c, name = nothing; raise_refusals = false)
    state = _door_call(c, "get_state", Dict{String,Any}())
    # A laboratory's workbenches, then a REAL account's (paper among them).
    every = Any[b for area in ("laboratories", "accounts") for home in get(state, area, Any[]) for b in get(home, "benches", Any[])]
    pick(x) = Bench(c, x["uri"], get(x, "name", nothing), raise_refusals, nothing, false)
    if name !== nothing
        for x in every
            (get(x, "uri", nothing) == name || get(x, "name", nothing) == name) && return pick(x)
        end
        names = join(("'" * string(get(x, "name", "")) * "'" for x in every), ", ")
        throw(McpError("no workbench is named '" * string(name) * "'; there are " * (isempty(names) ? "none" : names)))
    end
    isempty(every) && throw(McpError("the workspace holds no laboratory workbench"))
    selected = get(state, "selected", nothing)
    for x in every
        selected !== nothing && get(x, "uri", nothing) == selected && return pick(x)
    end
    pick(every[1])
end

"The workbench's markets."
function markets(b::Bench)
    if b.markets === nothing
        state = _read_uri(b, b.uri)
        b.markets = String[m isa AbstractString ? m : m["symbol"] for m in get(state, "markets", Any[])]
    end
    copy(b.markets)
end

# Every read through the resource_read tool: a door is anything `call` takes, the connection or the engine's own.
_read_uri(b::Bench, uri) = _door_call(b.client, "resource_read", Dict{String,Any}("uri" => uri))
# A workbench with no engine mounted (a clone, through the application) is selected - the window shows it, which is how
# Bentrix mounts one - and waited for, at most a minute.
function _mount(b::Bench)
    b.mounted && return
    b.mounted = true
    get(_read_uri(b, b.uri), "engine", nothing) == "none" || return
    _door_call(b.client, "select_bench", Dict{String,Any}("bench" => b.uri))
    for _ in 1:600
        get(_read_uri(b, b.uri), "engine", nothing) == "none" || return
        sleep(0.1)
    end
end

_put!(a, k, v) = (v === nothing || (a[k] = v); nothing)
# A ticket as an integer: the JSON reader gives every number as a Float64, and the tool takes a ticket whole.
_ticket(t) = (v = t isa AbstractDict ? t["ticket"] : t; v isa AbstractFloat && isinteger(v) ? Int64(v) : v)
_moment(t) = t === nothing ? nothing : t
# A whole number of an answer: the JSON reader hands every number as a float, and a group or a moment is whole.
_whole(v) = v isa AbstractFloat && isinteger(v) ? Int64(v) : v

function _symbol(b::Bench, symbol)
    symbol !== nothing && return symbol
    ms = markets(b)
    length(ms) == 1 && return ms[1]
    throw(McpError("this workbench holds " * string(length(ms)) * " markets (" * join(ms, ", ") * "): name the symbol"))
end

function _answered(b::Bench, raw)
    a = Answer(raw)
    !a.ok && b.raise && throw(Refused(a))
    a
end

_read(b::Bench, tail, after = nothing) = _read_uri(b, b.uri * "/" * tail * (after === nothing ? "" : "?after=" * _escape(after)))

function _quote(page, symbol)
    for q in get(page, "items", Any[])
        get(q, "symbol", nothing) == symbol && return q
    end
    nothing
end

function _stream(b::Bench, tail)
    all = Any[]
    after = nothing
    while true
        page = _read(b, tail, after)
        items = get(page, "items", Any[])
        isempty(items) && return all
        append!(all, items)
        after = get(page, "next", nothing)
        after isa AbstractString || return all
    end
end

# To the next close: a workbench that has lived through no tick steps one first (a jump never invents a first quote),
# then a candle of the interval; the closed candle is read back from the window.
function _step(b::Bench, interval, symbol)
    stood = get(_read_uri(b, b.uri), "cursor_ms", nothing)
    q = _quote(_read(b, "quotes"), symbol)
    (q === nothing || get(q, "at_ms", nothing) === nothing) && _door_call(b.client, "replay_step", Dict{String,Any}("bench" => b.uri, "unit" => "tick", "n" => 1))
    moved = _door_call(b.client, "replay_step", Dict{String,Any}("bench" => b.uri, "unit" => "candle", "n" => 1, "timeframe" => interval))
    now = get(moved, "cursor_ms", nothing)
    (now === nothing || now == stood) && return nothing
    got = _door_call(b.client, "bars_window", Dict{String,Any}("bench" => b.uri, "symbol" => symbol, "frames" => Any[interval], "limit" => 1))
    rows = get(got["markets"][symbol][interval], "rows", Any[])
    isempty(rows) ? nothing : Dict{String,Any}(k => rows[end][i] for (i, k) in enumerate(("time", "open", "high", "low", "close", "volume")))
end

"A market buy of lots; sl and tp as prices."
function buy(b::Bench, lots; symbol = nothing, sl = nothing, tp = nothing, tag = nothing, group = nothing)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    a["side"] = JSON.parse("\"buy\"")
    _put!(a, "volume", lots)
    _put!(a, "symbol", _symbol(b, symbol))
    _put!(a, "sl", sl)
    _put!(a, "tp", tp)
    _put!(a, "tag", tag)
    _put!(a, "group", group)
    _answered(b, _door_call(b.client, "order_market", a))
end

"A market sell of lots; sl and tp as prices."
function sell(b::Bench, lots; symbol = nothing, sl = nothing, tp = nothing, tag = nothing, group = nothing)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    a["side"] = JSON.parse("\"sell\"")
    _put!(a, "volume", lots)
    _put!(a, "symbol", _symbol(b, symbol))
    _put!(a, "sl", sl)
    _put!(a, "tp", tp)
    _put!(a, "tag", tag)
    _put!(a, "group", group)
    _answered(b, _door_call(b.client, "order_market", a))
end

"A pending order: kind buy_limit, sell_limit, buy_stop, sell_stop, buy_stop_limit or sell_stop_limit."
function pending(b::Bench, kind, price, lots; symbol = nothing, sl = nothing, tp = nothing, stop_limit = nothing, expires = nothing, tag = nothing, group = nothing)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _put!(a, "kind", kind)
    _put!(a, "price", price)
    _put!(a, "volume", lots)
    _put!(a, "symbol", _symbol(b, symbol))
    _put!(a, "sl", sl)
    _put!(a, "tp", tp)
    _put!(a, "stop_limit", stop_limit)
    _put!(a, "expires_ms", _moment(expires))
    _put!(a, "tag", tag)
    _put!(a, "group", group)
    _answered(b, _door_call(b.client, "order_pending", a))
end

"Only what is named changes: a position's or an order's stop, target, or a pending order's price; 0 removes a level."
function modify(b::Bench, ticket; sl = nothing, tp = nothing, price = nothing)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _put!(a, "ticket", _ticket(ticket))
    _put!(a, "sl", sl)
    _put!(a, "tp", tp)
    _put!(a, "price", price)
    _answered(b, _door_call(b.client, "order_modify", a))
end

"Close a position, all of it or lots of it, or cancel a pending order."
function Base.close(b::Bench, ticket; lots = nothing)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _put!(a, "ticket", _ticket(ticket))
    _put!(a, "volume", lots)
    _answered(b, _door_call(b.client, "order_close", a))
end

"Close every position, or one market's, or one group's; nothing open is an answer, not a refusal."
function close_all(b::Bench; symbol = nothing, group = nothing)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _put!(a, "symbol", symbol)
    _put!(a, "group", group)
    _answered(b, _door_call(b.client, "order_close_all", a))
end

"Close a position and open the same size the other way, as one act."
function reverse(b::Bench, ticket)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _put!(a, "ticket", _ticket(ticket))
    _answered(b, _door_call(b.client, "order_reverse", a))
end

"Stop following a position's trailing stop; its stop stays where the trail left it."
function untrail(b::Bench, ticket)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _put!(a, "ticket", _ticket(ticket))
    _answered(b, _door_call(b.client, "order_untrail", a))
end

"A group of orders under a label: its number, for buy's and close_all's group."
function group(b::Bench, label)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _put!(a, "label", label)
    _whole(get(_door_call(b.client, "group_open", a), "group", nothing))
end

"A trailing stop at points from the price, the venue's own."
function trail(b::Bench, ticket, points)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _put!(a, "ticket", _ticket(ticket))
    _put!(a, "points", points)
    _answered(b, _door_call(b.client, "order_trail", a))
end

"Cancel a pending order; the same act as close on an order's ticket."
function cancel(b::Bench, ticket)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _put!(a, "ticket", _ticket(ticket))
    _answered(b, _door_call(b.client, "order_close", a))
end

"What an order would cost and hold - its margin, its money a point, its price - sending nothing."
function preview(b::Bench, side, lots; symbol = nothing)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _put!(a, "side", side)
    _put!(a, "volume", lots)
    _put!(a, "symbol", _symbol(b, symbol))
    _door_call(b.client, "order_preview", a)
end

"What the book holds by market: lots net and gross, each market's notional, the account's ratios."
function exposure(b::Bench)
    _mount(b)
    _read(b, "exposure")
end

"The last closed candles of interval, oldest first."
function bars(b::Bench; interval = "M1", limit = 100, symbol = nothing)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _put!(a, "timeframe", interval)
    _put!(a, "limit", limit)
    _put!(a, "symbol", _symbol(b, symbol))
    page = _door_call(b.client, "bars_get", a)
    rows = get(page, "bars", Any[])
    get(page, "last_forming", false) === true && !isempty(rows) ? rows[1:end-1] : rows
end

"The book: positions, orders and the account."
function book(b::Bench)
    _mount(b)
    _read(b, "book")
end

"The open positions."
function positions(b::Bench)
    _mount(b)
    get(_read(b, "book"), "positions", Any[])
end

"The resting orders."
function orders(b::Bench)
    _mount(b)
    get(_read(b, "book"), "orders", Any[])
end

"The account: balance, equity, margin, free margin, currency."
function account(b::Bench)
    _mount(b)
    _read(b, "account")
end

"Every deal, oldest first."
function deals(b::Bench)
    _mount(b)
    _stream(b, "deals")
end

"The venue's event log, oldest first."
function events(b::Bench)
    _mount(b)
    _stream(b, "events")
end

"Every order the workbench was sent, oldest first: what it became and when."
function order_history(b::Bench)
    _mount(b)
    _stream(b, "orders")
end

"The market's bid and ask at the clock, or none."
function quote_now(b::Bench; symbol = nothing)
    _mount(b)
    _quote(_read(b, "quotes"), _symbol(b, symbol))
end

"A market's facts as numbers: digits, point, contract, volumes, stops level, swaps, sessions."
function spec(b::Bench; symbol = nothing)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _put!(a, "symbol", _symbol(b, symbol))
    _door_call(b.client, "symbol_info", a)
end

"Several timeframes at once, closed candles only, each with its forming candle."
function window(b::Bench, frames; limit = 100, symbol = nothing)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    a["include_forming"] = JSON.parse("true")
    _put!(a, "frames", _array(frames))
    _put!(a, "limit", limit)
    _put!(a, "symbol", _symbol(b, symbol))
    _door_call(b.client, "bars_window", a)
end

"Its conditions and their digest."
function manifest(b::Bench)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _door_call(b.client, "bench_manifest", a)
end

"To the next close of interval: the closed candle and where the clock stands, or none where it moves no further."
function Base.step(b::Bench; interval = "M1", symbol = nothing)
    _mount(b)
    _step(b, interval, _symbol(b, symbol))
end

"Forward to a moment, at most the days' last; where the clock stands."
function advance(b::Bench, to)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    a["stop_at_end"] = JSON.parse("true")
    _put!(a, "to_ms", _moment(to))
    _whole(get(_door_call(b.client, "replay_seek", a), "cursor_ms", nothing))
end

"Back to a moment; refused with its door when that would undo a deal, unless undo_deals."
function rewind(b::Bench, to; undo_deals = false)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _put!(a, "to_ms", _moment(to))
    _put!(a, "undo_deals", undo_deals)
    _door_call(b.client, "replay_seek", a)
end

"A checkpoint to a file."
function save(b::Bench, name)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _put!(a, "path", name)
    _door_call(b.client, "checkpoint_save", a)
end

"A checkpoint back, refused under other conditions."
function load(b::Bench, name)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _put!(a, "path", name)
    _door_call(b.client, "checkpoint_load", a)
end

"A workbench alike, in this one's state by default."
function clone(b::Bench; state = true, name = nothing)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    _put!(a, "state", state)
    _put!(a, "name", name)
    made = _door_call(b.client, "bench_clone", a)
    Bench(b.client, made["uri"], get(made, "name", nothing), b.raise, nothing, false)
end

"Keep where it stands, to watch on the chart: a clone in its state, under a name."
function keep(b::Bench, name)
    _mount(b)
    a = Dict{String,Any}("bench" => b.uri)
    a["state"] = JSON.parse("true")
    _put!(a, "name", name)
    made = _door_call(b.client, "bench_clone", a)
    Bench(b.client, made["uri"], get(made, "name", nothing), b.raise, nothing, false)
end

